text:
```yaml
design:
  schema: fpga-design-agent/project/v1
  name: vmed_video_filter
  board: nexys_a7_100t
  clocks:
    - {name: sys_clk, source: board, port: CLK100MHZ, mhz: 100}
    - {name: pixel_clk, source: mmcm, from: sys_clk, mhz: 74.25}
  resets:
    - {name: sys_reset, domain: sys_clk, polarity: active_low, style: sync, from: CPU_RESETN, via: reset_sync}
    - {name: pixel_reset, domain: pixel_clk, polarity: active_low, style: sync, from: sys_reset, via: reset_sync}
  shell: {design_id: VMED, clock: sys_clk, reset: sys_reset}
  modules:
    - name: pattern_timing
      kind: rtl
      clocks: {pixel_clk: pixel_clk}
      resets: {pixel_reset: pixel_reset}
      window_base: 0x00
      register_crossings: {PATTERN: xpm_cdc_handshake, FRAME_COUNT: xpm_cdc_handshake}
    - name: median_filter
      kind: rtl
      clocks: {pixel_clk: pixel_clk}
      resets: {pixel_reset: pixel_reset}
    - name: vga_output
      kind: rtl
      clocks: {pixel_clk: pixel_clk}
      resets: {pixel_reset: pixel_reset}
  connections:
    - {from: pattern_timing.out, to: median_filter.in}
    - {from: median_filter.out, to: vga_output.in}
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: sys_clk}
    - {name: CPU_RESETN, dir: in, drive: input, to: sys_reset}
    - {name: BTNC, dir: in, drive: input, to: vga_output.blank_button}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: "VGA_HS", dir: out, drive: push-pull, from: vga_output.hsync}
    - {name: "VGA_VS", dir: out, drive: push-pull, from: vga_output.vsync}
    - {name: "VGA_R[3:0]", dir: out, drive: push-pull, from: vga_output.red}
    - {name: "VGA_G[3:0]", dir: out, drive: push-pull, from: vga_output.green}
    - {name: "VGA_B[3:0]", dir: out, drive: push-pull, from: vga_output.blue}
    - {name: "LED[0]", dir: out, drive: push-pull, from: pixel_clk.locked}
  owned: []
  assumptions:
    - id: A-1
      text: "The filter's out-of-picture neighbourhood samples use edge replication."
      default: "Replicate the nearest active-picture pixel at each boundary."
      reason: "This is the supplied defaulted answer for the filter boundary rule."
      affects: [median_filter]
      status: resolved
    - id: A-2
      text: "The UART-selectable patterns are assigned numeric values."
      default: "0=colour bars, 1=grayscale ramp, 2=checkerboard; colour bars are selected at startup."
      reason: "The supplied answer names the patterns and startup selection but does not assign numbers."
      affects: [pattern_timing.contract.registers, pattern_timing]
      status: open
    - id: A-3
      text: "The shell uses the supplied ASCII command and reply format."
      default: "Newline-terminated P<n> and F commands with newline-terminated ASCII replies."
      reason: "This is the supplied defaulted answer for the UART command and response format."
      affects: [fpga_shell, pattern_timing]
      status: resolved
    - id: A-4
      text: "The frame counter is 32-bit, starts at zero after reset, and increments once per completed displayed frame."
      default: "Use the supplied 32-bit completed-frame counter behavior."
      reason: "This is the supplied defaulted answer for frame counting."
      affects: [pattern_timing.contract.registers]
      status: resolved
    - id: A-5
      text: "Pixel-clock stability is determined by the clock-generation primitive's locked indication."
      default: "Treat the clock as stable when locked is asserted."
      reason: "This is the supplied defaulted answer for pixel-clock stability."
      affects: [vga_output, pixel_clk, LED[0]]
      status: resolved
    - id: A-6
      text: "CPU_RESETN is the external active-low reset, synchronized in each clock domain."
      default: "Use CPU_RESETN as the reset source."
      reason: "The specification does not name a reset source; CPU_RESETN is the board reset pin."
      affects: [design.resets]
      status: open
    - id: A-7
      text: "The pixel clock is generated from the 100 MHz board clock by an MMCM."
      default: "Use an MMCM to generate 74.25 MHz."
      reason: "The required pixel frequency differs from the available board clock, and an MMCM is a standard Nexys A7 clock-generation choice."
      affects: [design.clocks.pixel_clk]
      status: open

contracts:
  pattern_timing:
    schema: fpga-design-agent/contract/v1
    module: pattern_timing
    summary: "Generates 720p60 raster timing and selectable test-pattern pixels; exposes the pattern selector and frame counter in the shell register window."
    clocks:
      - {name: pixel_clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: pixel_reset, port: rst, clock: pixel_clk, polarity: active_low, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: pattern_select, dir: in, width: 2, clock: pixel_clk, reset_value: 0}
      - {name: frame_count, dir: out, width: 32, clock: pixel_clk, reset_value: 0}
      - {name: m_axis_tvalid, dir: out, clock: pixel_clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: pixel_clk}
      - {name: m_axis_tdata, dir: out, width: 36, clock: pixel_clk}
    data_formats:
      - {name: raster_x, format: u11, packing: "Raster horizontal coordinate"}
      - {name: raster_y, format: u10, packing: "Raster vertical coordinate"}
      - {name: channel, format: u4, packing: "One unsigned VGA colour channel"}
      - {name: flag, format: u1, packing: "One boolean raster or sync flag"}
    interfaces:
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: pixel_clk
        reset: pixel_reset
        tdata:
          width: 36
          fields:
            - {name: x, bits: [35, 25], format: raster_x}
            - {name: y, bits: [24, 15], format: raster_y}
            - {name: red, bits: [14, 11], format: channel}
            - {name: green, bits: [10, 7], format: channel}
            - {name: blue, bits: [6, 3], format: channel}
            - {name: active, bits: [2, 2], format: flag}
            - {name: hsync, bits: [1, 1], format: flag}
            - {name: vsync, bits: [0, 0], format: flag}
        backpressure: false
        source_gaps: false
    registers:
      bus: top
      map:
        - name: PATTERN
          offset: 0x00
          access: RW
          reset: 0
          width: 2
          volatile: false
          fields:
            - {name: pattern_select, bits: [1, 0], port: pattern_select}
        - name: FRAME_COUNT
          offset: 0x04
          access: RO
          reset: 0
          width: 32
          volatile: true
          fields:
            - {name: frame_count, bits: [31, 0], port: frame_count}
    throughput:
      - {interface: out, beats_per_cycle: 1}

  median_filter:
    schema: fpga-design-agent/contract/v1
    module: median_filter
    summary: "Computes the per-channel 3 x 3 median for active pixels and forwards aligned raster timing."
    clocks:
      - {name: pixel_clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: pixel_reset, port: rst, clock: pixel_clk, polarity: active_low, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: s_axis_tvalid, dir: in, clock: pixel_clk}
      - {name: s_axis_tready, dir: out, clock: pixel_clk, reset_value: 0}
      - {name: s_axis_tdata, dir: in, width: 36, clock: pixel_clk}
      - {name: m_axis_tvalid, dir: out, clock: pixel_clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: pixel_clk}
      - {name: m_axis_tdata, dir: out, width: 36, clock: pixel_clk}
    data_formats:
      - {name: raster_x, format: u11, packing: "Raster horizontal coordinate"}
      - {name: raster_y, format: u10, packing: "Raster vertical coordinate"}
      - {name: channel, format: u4, packing: "One unsigned VGA colour channel"}
      - {name: flag, format: u1, packing: "One boolean raster or sync flag"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: pixel_clk
        reset: pixel_reset
        tdata:
          width: 36
          fields:
            - {name: x, bits: [35, 25], format: raster_x}
            - {name: y, bits: [24, 15], format: raster_y}
            - {name: red, bits: [14, 11], format: channel}
            - {name: green, bits: [10, 7], format: channel}
            - {name: blue, bits: [6, 3], format: channel}
            - {name: active, bits: [2, 2], format: flag}
            - {name: hsync, bits: [1, 1], format: flag}
            - {name: vsync, bits: [0, 0], format: flag}
        backpressure: false
        source_gaps: false
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: pixel_clk
        reset: pixel_reset
        tdata:
          width: 36
          fields:
            - {name: x, bits: [35, 25], format: raster_x}
            - {name: y, bits: [24, 15], format: raster_y}
            - {name: red, bits: [14, 11], format: channel}
            - {name: green, bits: [10, 7], format: channel}
            - {name: blue, bits: [6, 3], format: channel}
            - {name: active, bits: [2, 2], format: flag}
            - {name: hsync, bits: [1, 1], format: flag}
            - {name: vsync, bits: [0, 0], format: flag}
        backpressure: false
        source_gaps: false
    throughput:
      - {interface: in, beats_per_cycle: 1}
      - {interface: out, beats_per_cycle: 1}

  vga_output:
    schema: fpga-design-agent/contract/v1
    module: vga_output
    summary: "Drives VGA colour and sync pins from the filtered raster stream, blanking colour as required."
    clocks:
      - {name: pixel_clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: pixel_reset, port: rst, clock: pixel_clk, polarity: active_low, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: pixel_stable, dir: in, width: 1, clock: async}
      - {name: blank_button, dir: in, width: 1, clock: async}
      - {name: s_axis_tvalid, dir: in, clock: pixel_clk}
      - {name: s_axis_tready, dir: out, clock: pixel_clk, reset_value: 0}
      - {name: s_axis_tdata, dir: in, width: 36, clock: pixel_clk}
      - {name: red, dir: out, width: 4, clock: pixel_clk, reset_value: 0}
      - {name: green, dir: out, width: 4, clock: pixel_clk, reset_value: 0}
      - {name: blue, dir: out, width: 4, clock: pixel_clk, reset_value: 0}
      - {name: hsync, dir: out, width: 1, clock: pixel_clk, reset_value: 0}
      - {name: vsync, dir: out, width: 1, clock: pixel_clk, reset_value: 0}
    data_formats:
      - {name: raster_x, format: u11, packing: "Raster horizontal coordinate"}
      - {name: raster_y, format: u10, packing: "Raster vertical coordinate"}
      - {name: channel, format: u4, packing: "One unsigned VGA colour channel"}
      - {name: flag, format: u1, packing: "One boolean raster or sync flag"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: pixel_clk
        reset: pixel_reset
        tdata:
          width: 36
          fields:
            - {name: x, bits: [35, 25], format: raster_x}
            - {name: y, bits: [24, 15], format: raster_y}
            - {name: red, bits: [14, 11], format: channel}
            - {name: green, bits: [10, 7], format: channel}
            - {name: blue, bits: [6, 3], format: channel}
            - {name: active, bits: [2, 2], format: flag}
            - {name: hsync, bits: [1, 1], format: flag}
            - {name: vsync, bits: [0, 0], format: flag}
        backpressure: false
        source_gaps: false
    throughput:
      - {interface: in, beats_per_cycle: 1}

module_specs:
  fpga_shell: |
    Always-present test shell. Owns the USB-UART and a register window at 0x80-0xFF.
    The shell uses the VMED design ID and 115200 baud. It parses newline-terminated
    ASCII P<n> pattern-selection commands and F frame-counter queries, and returns
    newline-terminated ASCII replies. Its UART RX input is connected to UART_TXD_IN;
    its UART TX output is connected to UART_RXD_OUT. The top-level register window
    decodes the pattern_timing registers at window_base 0x00.
  pattern_timing: |
    Generates the complete 1650-by-750 CEA-861 720p60 raster at pixel_clk, including
    the specified positive sync timing and the active-picture flag. Produces eight
    160-pixel vertical colour bars by default, plus a grayscale ramp and checkerboard
    selected by the pattern register. Pattern numbers are 0=bars, 1=grayscale,
    and 2=checkerboard. Increments the 32-bit frame counter once per completed
    displayed frame and resets it to zero.
  median_filter: |
    For each active output pixel, computes the median of the nine samples in the
    corresponding 3 x 3 neighbourhood independently for red, green, and blue.
    At active-picture boundaries, replicates the nearest active-picture pixel to
    complete the neighbourhood. Delays the raster metadata with the filtered
    picture so active timing and sync remain aligned. Processes the continuous
    raster without inserting gaps or requiring backpressure.
  vga_output: |
    Drives four-bit red, green, and blue VGA channels and the filtered horizontal
    and vertical sync. Drives all colour channels to zero outside active video,
    while BTNC is pressed, while pixel_clk.locked is deasserted, or during reset.
    Sync outputs follow the aligned filtered raster timing.

requirements:
  - id: S-1
    text: "Generate VGA timing at 1280 x 720 active pixels and 60 Hz using CEA-861 720p60 timing: 74.25 MHz pixel clock, 1650 pixel clocks per line (1280 active, 110 front porch, 40 sync, 220 back porch), 750 lines per frame (720 active, 5 front porch, 5 sync, 20 back porch), with positive horizontal and vertical sync."
    proof: [simulation, hardware, analysis]
    modules: [pattern_timing, top]
  - id: S-2
    text: "With the default pattern selected, display eight vertical colour bars, each 160 active pixels wide, in this order: white, yellow, cyan, green, magenta, red, blue, black."
    proof: [simulation, hardware]
    modules: [pattern_timing, top]
  - id: S-3
    text: "For each active output pixel, output the median of the nine samples in its 3 x 3 neighbourhood independently for each colour channel."
    proof: [simulation, formal]
    modules: [median_filter]
  - id: S-4
    text: "Keep the filtered picture and the horizontal and vertical sync signals aligned at the VGA output, with the same active-picture timing as the unfiltered timing generator."
    proof: [simulation, hardware]
    modules: [median_filter, vga_output, top]
  - id: S-5
    text: "Drive all colour outputs to zero outside the active picture, while BTNC is pressed, or while the pixel clock is not stable."
    proof: [simulation, hardware]
    modules: [vga_output, top]
  - id: S-6
    text: "Illuminate LED[0] when the pixel clock is stable."
    proof: [simulation, hardware]
    modules: [top]
  - id: S-7
    text: "Provide a 115200-baud USB-UART interface identified as VMED that allows the host to select a test pattern and read a frame counter."
    proof: [simulation, hardware]
    modules: [fpga_shell, pattern_timing, top]

sources:
  "design.board": "The board is nexys_a7_100t."
  "design.shell.design_id": "design ID \"VMED\"."
  "design.clocks.pixel_clk.mhz": "Timing is CEA-861 720p60: 74.25 MHz pixel clock"
  "pattern_timing.contract.clocks.pixel_clk.max_mhz": "Timing is CEA-861 720p60: 74.25 MHz pixel clock"
  "median_filter.contract.clocks.pixel_clk.max_mhz": "Timing is CEA-861 720p60: 74.25 MHz pixel clock"
  "vga_output.contract.clocks.pixel_clk.max_mhz": "Timing is CEA-861 720p60: 74.25 MHz pixel clock"
  "design.board_ports.CLK100MHZ": "The board is nexys_a7_100t."
  "pattern_timing.contract.registers": "Through it I choose the pattern and read a frame counter."
  "pattern_timing.contract.interfaces.out.tdata": "The picture comes from a 720p timing generator with a test pattern: eight vertical colour bars of 160 pixels (white, yellow, cyan, green, magenta, red, blue, black) by default."
  "median_filter.contract.interfaces.in.tdata": "The median filter takes each pixel's 3 x 3 neighbourhood and outputs the median of each colour channel."
  "median_filter.contract.interfaces.out.tdata": "The median filter takes each pixel's 3 x 3 neighbourhood and outputs the median of each colour channel."
  "vga_output.contract.ports.red": "Use 4 bits per colour channel."
  "vga_output.contract.ports.green": "Use 4 bits per colour channel."
  "vga_output.contract.ports.blue": "Use 4 bits per colour channel."
  "design.board_ports.BTNC": "Outside the active picture, and while the centre button `BTNC` is pressed or the pixel clock is not stable, the colour outputs are 0."
  "design.board_ports.LED[0]": "`LED[0]` lights when the pixel clock is stable."
  "design.board_ports.VGA_HS": "with positive horizontal and vertical sync."
  "design.board_ports.VGA_VS": "with positive horizontal and vertical sync."
  "design.board_ports.VGA_R[3:0]": "Use 4 bits per colour channel."
  "design.board_ports.VGA_G[3:0]": "Use 4 bits per colour channel."
  "design.board_ports.VGA_B[3:0]": "Use 4 bits per colour channel."
  "design.board_ports.UART_TXD_IN": "The test shell is on the USB-UART at 115200 baud"
  "design.board_ports.UART_RXD_OUT": "The test shell is on the USB-UART at 115200 baud"
  "pattern_timing.contract.registers.PATTERN": "Through it I choose the pattern"
  "pattern_timing.contract.registers.FRAME_COUNT": "and read a frame counter."
  "pattern_timing.contract.ports.pattern_select": "Provide the specified colour bars, a grayscale ramp, and a checkerboard; use the colour bars at startup."
  "pattern_timing.contract.ports.frame_count": "Use a 32-bit unsigned counter that increments once per completed displayed frame and starts at zero after power-up or reset."
  "median_filter": "For each active output pixel, output the median of the nine samples in its 3 x 3 neighbourhood independently for each colour channel."
  "vga_output": "Drive all colour outputs to zero outside the active picture, while BTNC is pressed, or while the pixel clock is not stable."
  "fpga_shell": "The test shell (shell/rtl/fpga_shell.sv) is always present: it owns the USB-UART and a register window at 0x80-0xFF"
  "design.modules.pattern_timing.window_base": "a module's registers on `bus: top` are placed in that window at `window_base`."
  "pattern_timing.contract.data_formats.raster_x": "1280 active"
  "pattern_timing.contract.data_formats.raster_y": "720 active"
  "pattern_timing.contract.data_formats.channel": "Use 4 bits per colour channel."
  "design.assumptions.A-1": "Replicate the nearest active-picture pixel at each boundary, so every active output pixel has a complete 3 x 3 neighbourhood."
  "design.assumptions.A-2": "Provide the specified colour bars, a grayscale ramp, and a checkerboard; use the colour bars at startup."
  "design.assumptions.A-3": "Use newline-terminated ASCII commands `P<n>` to select pattern number n and `F` to read the counter, with newline-terminated ASCII replies."
  "design.assumptions.A-4": "Use a 32-bit unsigned counter that increments once per completed displayed frame and starts at zero after power-up or reset."
  "design.assumptions.A-5": "Treat the clock as stable when the clock-generation primitive's locked indication is asserted."
  "design.assumptions.A-6": "The specification does not name a reset source; CPU_RESETN is the board reset pin."
  "design.assumptions.A-7": "The specification does not name the clock-generation primitive."

reasons:
  "design.name": "Use a short project identifier derived from the specified VMED video-filter design."
  "design.clocks.sys_clk": "The board clock is the system reference; CLK100MHZ is the Nexys A7-100T board clock pin."
  "design.clocks.pixel_clk": "The required 74.25 MHz pixel clock is derived from the board's 100 MHz reference with an MMCM."
  "design.resets.sys_reset": "Use the board's CPU_RESETN as an active-low external reset and synchronize its release in the system clock domain."
  "design.resets.pixel_reset": "Synchronize the system reset into the pixel-clock domain using reset_sync."
  "design.shell.clock": "The shell UART and register window use the 100 MHz system clock."
  "design.shell.reset": "Bind the always-present shell to the synchronized system reset."
  "design.modules.pattern_timing.window_base": "Choose offset 0x00 within the shell window's permitted module-register offset range; its two registers do not overlap."
  "design.modules.pattern_timing.kind": "Implement the timing and pattern generator as an RTL module."
  "design.modules.median_filter.kind": "Implement the median filter as an RTL module."
  "design.modules.vga_output.kind": "Implement the VGA output stage as an RTL module."
  "design.connections": "Use a single, point-to-point raster stream from timing generation through filtering to the VGA output stage; all three modules use the same pixel clock."
  "design.board_ports.CLK100MHZ": "Connect the board's reference-clock pin to the declared board clock."
  "design.board_ports.CPU_RESETN": "Use the board reset pin as the external reset source."
  "design.board_ports.BTNC": "Connect the button directly to the VGA output stage so colour blanking responds to the pressed button."
  "design.board_ports.UART_TXD_IN": "UART_TXD_IN is the FPGA-side UART receive input, so it feeds shell.uart_rx."
  "design.board_ports.UART_RXD_OUT": "UART_RXD_OUT is the FPGA-side UART transmit output, so it is driven by shell.uart_tx."
  "design.board_ports.VGA_HS": "Drive the board's horizontal sync pin from the aligned filtered sync."
  "design.board_ports.VGA_VS": "Drive the board's vertical sync pin from the aligned filtered sync."
  "design.board_ports.VGA_R[3:0]": "Bind the four-bit red output to the four VGA red pins."
  "design.board_ports.VGA_G[3:0]": "Bind the four-bit green output to the four VGA green pins."
  "design.board_ports.VGA_B[3:0]": "Bind the four-bit blue output to the four VGA blue pins."
  "design.board_ports.LED[0]": "Drive LED[0] directly from the clock-generation primitive's locked indication."
  "pattern_timing.contract.parameters": "No configurable hardware parameters are required; timing values are fixed by the specification."
  "pattern_timing.contract.resets.pixel_reset": "Use the synchronized active-low reset in the pixel-clock domain."
  "pattern_timing.contract.ports.clk": "This module runs from the 74.25 MHz pixel clock."
  "pattern_timing.contract.ports.rst": "This module resets in the pixel-clock domain."
  "pattern_timing.contract.ports.pattern_select": "A two-bit encoding covers the three selectable patterns; encoding 0 is the startup colour-bars selection."
  "pattern_timing.contract.ports.frame_count": "A 32-bit unsigned count is required by the supplied frame-counter answer."
  "pattern_timing.contract.ports.m_axis_tvalid": "A continuously generated raster uses a valid signal asserted for each raster beat."
  "pattern_timing.contract.ports.m_axis_tready": "The stream interface includes ready; this fixed-rate video source does not pause for backpressure."
  "pattern_timing.contract.ports.m_axis_tdata": "Pack raster position, RGB channels, active-video state, and both syncs into one point-to-point stream word."
  "pattern_timing.contract.data_formats": "Use unsigned formats matching the chosen coordinate, channel, and flag field widths."
  "pattern_timing.contract.interfaces.out.protocol": "AXI4-Stream provides a point-to-point pixel stream with explicit valid and ready signals."
  "pattern_timing.contract.interfaces.out.tdata": "Pack the active coordinates, RGB values, active flag, and syncs so the filter can process pixels and preserve raster timing."
  "pattern_timing.contract.interfaces.out.backpressure": "A fixed-rate video raster cannot be stalled without changing its timing."
  "pattern_timing.contract.interfaces.out.source_gaps": "The timing generator emits one beat for every pixel clock."
  "pattern_timing.contract.registers.PATTERN": "Use offset 0 for the writable pattern selector."
  "pattern_timing.contract.registers.FRAME_COUNT": "Use aligned offset 4 for the readable 32-bit frame counter."
  "pattern_timing.contract.throughput.out": "The raster has one pixel beat per pixel clock."
  "median_filter.contract.parameters": "No configurable filter parameters are required by the specification."
  "median_filter.contract.resets.pixel_reset": "Use the synchronized active-low reset in the pixel-clock domain."
  "median_filter.contract.ports.clk": "The filter processes the pixel stream in the pixel-clock domain."
  "median_filter.contract.ports.rst": "Reset the filter in the pixel-clock domain."
  "median_filter.contract.ports.s_axis_tvalid": "Receive a valid raster beat from the timing generator."
  "median_filter.contract.ports.s_axis_tready": "The filter accepts the continuous raster without stalling its source."
  "median_filter.contract.ports.s_axis_tdata": "The filter needs pixel channels and raster metadata to form neighbourhoods and keep timing aligned."
